"use client";
import { useState } from "react";
import type { ComponentProps } from "react";
import { ListPage } from "../../../library/pages/ListPage";
import { Select } from "../../../library/components/Select";
import { TextField } from "../../../library/components/TextField";
import products from "../../../library/fixtures/products.json";

type Product = { id: string; name: string; category: string; price: number; description: string; stock: number };

const allProducts = products as Product[];

const money = (n: number) => "$" + n.toFixed(2);

export function CatalogPage(props: ComponentProps<typeof ListPage> & object) {
  const [category, setCategory] = useState("all");
  const [query, setQuery] = useState("");
  const needle = query.trim().toLowerCase();
  const shown = allProducts.filter((p) => (category === "all" || p.category === category) && p.name.toLowerCase().includes(needle));
  return (
    <ListPage
      {...props}
      title="Products"
      toolbar={
        <>
          <Select label="Category" value={category} onValueChange={setCategory} options={[{ value: "all", label: "All" }, { value: "Clothing", label: "Clothing" }, { value: "Home", label: "Home" }, { value: "Electronics", label: "Electronics" }]} />
          <TextField label="Search" value={query} onChange={setQuery} type="search" />
        </>
      }
      empty={<p>No products found</p>}
    >
      {shown.length ? shown.map((p) => (
        <div key={p.id} className="flex flex-col gap-1 rounded-md border border-slate-200 p-4">
          <a href={"/products/" + p.id} className="font-semibold underline">{p.name}</a>
          <span className="text-sm text-slate-600">{p.category}</span>
          <span className="text-sm">{money(p.price)}</span>
        </div>
      )) : null}
    </ListPage>
  );
}

"use client";
import { useEffect, useState } from "react";

export type CartLine = { id: string; quantity: number };

const KEY = "line-cart";
const EVENT = "line-cart-changed";

export function readCart(): CartLine[] {
  try {
    const raw = window.localStorage.getItem(KEY);
    return raw ? (JSON.parse(raw) as CartLine[]) : [];
  } catch {
    return [];
  }
}

export function writeCart(lines: CartLine[]) {
  try {
    window.localStorage.setItem(KEY, JSON.stringify(lines));
  } catch {
    // storage unavailable: the cart still works for this page view
  }
  window.dispatchEvent(new Event(EVENT));
}

export function addToCart(id: string, quantity: number) {
  const lines = readCart();
  const hit = lines.find((l) => l.id === id);
  if (hit) hit.quantity += quantity;
  else lines.push({ id, quantity });
  writeCart(lines);
}

export function setQuantity(id: string, quantity: number) {
  writeCart(readCart().map((l) => (l.id === id ? { ...l, quantity } : l)).filter((l) => l.quantity > 0));
}

export function removeFromCart(id: string) {
  writeCart(readCart().filter((l) => l.id !== id));
}

export function clearCart() {
  writeCart([]);
}

export function useCart(): CartLine[] {
  const [lines, setLines] = useState<CartLine[]>([]);
  useEffect(() => {
    const sync = () => setLines(readCart());
    sync();
    window.addEventListener(EVENT, sync);
    window.addEventListener("storage", sync);
    return () => {
      window.removeEventListener(EVENT, sync);
      window.removeEventListener("storage", sync);
    };
  }, []);
  return lines;
}

