"use client";
import { useState } from "react";
import type { ComponentProps } from "react";
import { useParams } from "next/navigation";
import { DetailPage } from "../../../library/pages/DetailPage";
import { Button } from "../../../library/components/Button";
import { TextField } from "../../../library/components/TextField";
import products from "../../../library/fixtures/products.json";
import { addToCart } from "../../../library/usecases/cart";

type Product = { id: string; name: string; category: string; price: number; description: string; stock: number };

const allProducts = products as Product[];

const money = (n: number) => "$" + n.toFixed(2);

export function ProductPage(_props: ComponentProps<typeof DetailPage> & object) {
  const params = useParams<{ id: string }>();
  const product = allProducts.find((p) => p.id === params.id);
  const [quantity, setQuantity] = useState("1");
  const [added, setAdded] = useState(false);
  if (!product) {
    return (
      <DetailPage title="Product not found" back={<a href="/">Back to products</a>}>
        <p>Product not found</p>
      </DetailPage>
    );
  }
  const addLine = () => {
    const n = Math.max(1, Math.floor(Number(quantity) || 1));
    addToCart(product.id, n);
    setAdded(true);
  };
  return (
    <DetailPage
      title={product.name}
      back={<a href="/">Back to products</a>}
      aside={
        <>
          <p className="text-xl font-semibold">{money(product.price)}</p>
          <TextField label="Quantity" type="number" min={1} value={quantity} onChange={(v) => { setQuantity(v); setAdded(false); }} />
          <Button label="Add to cart" onClick={addLine} />
          {added ? <p role="status">Added to cart</p> : null}
        </>
      }
    >
      <p className="text-sm text-slate-600">{product.category}</p>
      <p>{product.description}</p>
    </DetailPage>
  );
}

