"use client";
import type { ComponentProps } from "react";
import { ListPage } from "../../../library/pages/ListPage";
import { TextField } from "../../../library/components/TextField";
import { Button } from "../../../library/components/Button";
import products from "../../../library/fixtures/products.json";
import { useCart, setQuantity, removeFromCart } from "../../../library/usecases/cart";

type Product = { id: string; name: string; category: string; price: number; description: string; stock: number };

const allProducts = products as Product[];

const money = (n: number) => "$" + n.toFixed(2);

export function CartPage(_props: ComponentProps<typeof ListPage> & object) {
  const lines = useCart();
  const rows = lines.flatMap((l) => {
    const product = allProducts.find((p) => p.id === l.id);
    return product ? [{ id: l.id, quantity: l.quantity, product }] : [];
  });
  const subtotal = rows.reduce((s, r) => s + r.product.price * r.quantity, 0);
  const shipping = subtotal >= 100 ? 0 : 5;
  const total = subtotal + shipping;
  return (
    <ListPage
      title="Your cart"
      empty={
        <div className="flex flex-col gap-2">
          <p>Your cart is empty</p>
          <a href="/" className="underline">Continue shopping</a>
        </div>
      }
    >
      {rows.length ? (
        <>
          {rows.map((r) => (
            <div key={r.id} className="flex flex-col gap-2 rounded-md border border-slate-200 p-4">
              <p className="font-semibold">{r.product.name}</p>
              <p className="text-sm">Unit price {money(r.product.price)}</p>
              <TextField label={"Quantity for " + r.product.name} type="number" min={0} value={String(r.quantity)} onChange={(v) => setQuantity(r.id, Math.max(0, Math.floor(Number(v) || 0)))} />
              <p className="text-sm">Line total {money(r.product.price * r.quantity)}</p>
              <Button variant="secondary" label={"Remove " + r.product.name} onClick={() => removeFromCart(r.id)} />
            </div>
          ))}
          <div className="flex flex-col gap-2 rounded-md border border-slate-200 p-4">
            <p>Subtotal {money(subtotal)}</p>
            <p>Shipping {money(shipping)}</p>
            <p className="font-semibold">Total {money(total)}</p>
            <a href="/checkout" className="underline">Checkout</a>
          </div>
        </>
      ) : null}
    </ListPage>
  );
}

"use client";

export type OrderLine = { id: string; name: string; quantity: number; price: number };
export type Order = { number: string; lines: OrderLine[]; total: number; createdAt: string };

const KEY = "line-last-order";

/** A mock order service: no network, the order is kept in the browser for the confirmation page. */
export function placeOrder(lines: OrderLine[], total: number): Order {
  const order: Order = {
    number: String(Math.floor(100000 + Math.random() * 900000)),
    lines,
    total,
    createdAt: new Date().toISOString(),
  };
  try {
    window.sessionStorage.setItem(KEY, JSON.stringify(order));
  } catch {
    // storage unavailable: the confirmation page shows no order
  }
  return order;
}

export function readLastOrder(): Order | null {
  try {
    const raw = window.sessionStorage.getItem(KEY);
    return raw ? (JSON.parse(raw) as Order) : null;
  } catch {
    return null;
  }
}

