"use client";
import { useState } from "react";
import type { ComponentProps } from "react";
import { useRouter } from "next/navigation";
import { FormPage } from "../../../library/pages/FormPage";
import { TextField } from "../../../library/components/TextField";
import { Checkbox } from "../../../library/components/Checkbox";
import products from "../../../library/fixtures/products.json";
import { useCart, clearCart } from "../../../library/usecases/cart";
import { placeOrder } from "../usecases/orders";

type Product = { id: string; name: string; category: string; price: number; description: string; stock: number };

const allProducts = products as Product[];

const money = (n: number) => "$" + n.toFixed(2);

type Errors = Partial<Record<"name" | "email" | "address" | "city" | "postal" | "terms", string>>;

export function CheckoutPage(_props: ComponentProps<typeof FormPage> & object) {
  const router = useRouter();
  const lines = useCart();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [address, setAddress] = useState("");
  const [city, setCity] = useState("");
  const [postal, setPostal] = useState("");
  const [terms, setTerms] = useState(false);
  const [errors, setErrors] = useState<Errors>({});

  const rows = lines.flatMap((l) => {
    const product = allProducts.find((p) => p.id === l.id);
    return product ? [{ id: l.id, quantity: l.quantity, product }] : [];
  });
  const subtotal = rows.reduce((s, r) => s + r.product.price * r.quantity, 0);
  const total = subtotal + (subtotal >= 100 ? 0 : 5);

  if (rows.length === 0) {
    return (
      <main className="flex flex-col gap-4">
        <h1 className="text-2xl font-bold">Checkout</h1>
        <p>Your cart is empty</p>
        <a href="/" className="underline">Browse the products</a>
      </main>
    );
  }

  const submit = () => {
    const next: Errors = {};
    if (!name.trim()) next.name = "Full name is required";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) next.email = "Enter a valid email";
    if (!address.trim()) next.address = "Address is required";
    if (!city.trim()) next.city = "City is required";
    if (!/^\d{5}$/.test(postal.trim())) next.postal = "Postal code must be 5 digits";
    if (!terms) next.terms = "Accept the terms to continue";
    setErrors(next);
    if (Object.keys(next).length > 0) return;
    placeOrder(rows.map((r) => ({ id: r.id, name: r.product.name, quantity: r.quantity, price: r.product.price })), total);
    clearCart();
    router.push("/order/confirmation");
  };

  return (
    <FormPage
      title="Checkout"
      onSubmit={submit}
      submitLabel="Place order"
      aside={
        <div className="flex flex-col gap-2 rounded-md border border-slate-200 p-4">
          <p className="font-semibold">Order summary</p>
          {rows.map((r) => (
            <p key={r.id} className="text-sm">{r.product.name} x {r.quantity}: {money(r.product.price * r.quantity)}</p>
          ))}
          <p className="font-semibold">Total {money(total)}</p>
        </div>
      }
    >
      <TextField label="Full name" value={name} onChange={setName} error={errors.name} autoComplete="name" />
      <TextField label="Email" type="email" value={email} onChange={setEmail} error={errors.email} autoComplete="email" />
      <TextField label="Address" value={address} onChange={setAddress} error={errors.address} />
      <TextField label="City" value={city} onChange={setCity} error={errors.city} />
      <TextField label="Postal code" value={postal} onChange={setPostal} error={errors.postal} />
      <Checkbox label="I accept the terms" checked={terms} onCheckedChange={setTerms} error={errors.terms} />
    </FormPage>
  );
}

