"use client";
import { useEffect, useState } from "react";
import type { ComponentProps } from "react";
import { DetailPage } from "../../../library/pages/DetailPage";
import { readLastOrder } from "../usecases/orders";
import type { Order } from "../usecases/orders";

const money = (n: number) => "$" + n.toFixed(2);

export function ConfirmationPage(_props: ComponentProps<typeof DetailPage> & object) {
  const [order, setOrder] = useState<Order | null>(null);
  useEffect(() => {
    setOrder(readLastOrder());
  }, []);
  return (
    <DetailPage
      title="Thank you for your order"
      aside={<a href="/" className="underline">Continue shopping</a>}
    >
      {order ? (
        <div className="flex flex-col gap-2">
          <p className="font-semibold">Order #{order.number}</p>
          <ul className="flex flex-col gap-1">
            {order.lines.map((l) => (
              <li key={l.id} className="text-sm">{l.name} x {l.quantity}</li>
            ))}
          </ul>
          <p>Total paid {money(order.total)}</p>
        </div>
      ) : (
        <p>No order to show.</p>
      )}
    </DetailPage>
  );
}
